import{C as o,o as t,c as a,F as r,B as s,b as i,k as l}from"./chunks/framework.BiXHgXAn.js";const u=JSON.parse(`[{"title":"One Completion Engine for Every Shell","url":"/blog/completion-engine","date":{"time":1790812800000,"string":"2026-10-01"},"author":"vmaerten","tags":["new-features","completion"],"excerpt":"<p>Task has shipped shell completions for a long time. They were written as one\\nscript per shell: a Bash script, a Zsh script, a Fish script, one for PowerShell\\nand one for Nushell. Each of them had to work out on its own what your Taskfile\\ncontains and what flags Task accepts. Over the years, they drifted.</p>"},{"title":"Remote Taskfiles","url":"/blog/remote-taskfiles","date":{"time":1787011200000,"string":"2026-08-18"},"author":"pd93","tags":["experiments","remote","new-features"],"excerpt":"<p>It's finally time! After nearly 3 years as an experiment, we're excited to\\nannounce that today, <a href=\\"./../docs/remote-taskfiles.html\\">remote Taskfiles</a> have been made\\ngenerally available. No more setting flags or config to enable it. It is enabled\\nby default and will continue to work seamlessly with your existing remote\\ntaskfiles.</p>"},{"title":"GitHub Secure Open Source Fund","url":"/blog/github-secure-open-source-program","date":{"time":1786752000000,"string":"2026-08-15"},"author":"andreynering","tags":["github","security"],"excerpt":"<p>Did you know that GitHub has a special program to fund security in open source?\\nIt's the <a href=\\"https://github.com/open-source/github-secure-open-source-fund\\" target=\\"_blank\\" rel=\\"noreferrer\\">GitHub Secure Open Source Fund</a>. We were selected to participate\\nin session 4 that happened in May 2026 and it was really special for us.</p>"},{"title":"Using \`go tool task\`","url":"/blog/go-tool-task","date":{"time":1776124800000,"string":"2026-04-14"},"author":"andreynering","tags":["installation"],"excerpt":"<p>Do you know that you can use Task without really needing to install it?</p>\\n<p>If you work with Go, you probably depend on external binaries like linters, code\\ngenerators and... Task.</p>"},{"title":"Conditional Statements and Variable Prompts","url":"/blog/if-and-variable-prompt","date":{"time":1769212800000,"string":"2026-01-24"},"author":"vmaerten","tags":["new-features","variables"],"excerpt":"<p>The <a href=\\"https://github.com/go-task/task/releases/tag/v3.47.0\\" target=\\"_blank\\" rel=\\"noreferrer\\">v3.47.0</a> release is here, and it brings two exciting new features\\nto Task. Let's take a closer look at them!</p>"},{"title":"Announcing Built-in Core Utilities for Windows","url":"/blog/windows-core-utils","date":{"time":1757894400000,"string":"2025-09-15"},"author":"andreynering","tags":["windows","core-utils"],"excerpt":"<p>When I started Task back in 2017, one of my biggest goals was to build a task\\nrunner that would work well on all major platforms, including Windows. At the\\ntime, I was using Windows as my main platform, and it caught my attention how\\nmuch of a pain it was to get a working version of Make on Windows, for example.</p>"},{"title":"Any Variables","url":"/blog/any-variables","date":{"time":1715212800000,"string":"2024-05-09"},"author":"pd93","tags":["experiments","variables","new-features"],"excerpt":"<p>Task has always had variables, but even though you were able to define them\\nusing different YAML types, they would always be converted to strings by Task.\\nThis limited users to string manipulation and encouraged messy workarounds for\\nsimple problems. Starting from <a href=\\"https://github.com/go-task/task/releases/tag/v3.37.0\\" target=\\"_blank\\" rel=\\"noreferrer\\">v3.37.0</a>, this is no longer the case!\\nTask now supports most variable types, including <strong>booleans</strong>, <strong>integers</strong>,\\n<strong>floats</strong> and <strong>arrays</strong>!</p>"},{"title":"Introducing Experiments","url":"/blog/task-in-2023","date":{"time":1693612800000,"string":"2023-09-02"},"author":"pd93","tags":["roadmap","experiments","community"],"excerpt":"<p>Lately, Task has been growing extremely quickly and I've found myself thinking a\\nlot about the future of the project and how we continue to evolve and grow. I'm\\nnot much of a writer, but I think one of the things we could do better is to\\ncommunicate these kinds of thoughts to the community. So, with that in mind,\\nthis is the first (hopefully of many) blog posts talking about Task and what\\nwe're up to.</p>"}]`),m=JSON.parse('{"title":"Blog","description":"Latest news and updates from the Task team","frontmatter":{"title":"Blog","description":"Latest news and updates from the Task team","editLink":false},"headers":[],"relativePath":"blog/index.md","filePath":"next/blog/index.md"}'),g={name:"blog/index.md"},f=Object.assign(g,{setup(d){return(h,p)=>{const n=o("BlogPost");return t(),a("div",null,[(t(!0),a(r,null,s(l(u),e=>(t(),i(n,{key:e.url,title:e.title,url:e.url,date:e.date.string,author:e.author,description:e.excerpt,tags:e.tags},null,8,["title","url","date","author","description","tags"]))),128))])}}});export{m as __pageData,f as default};
